import Text_Detector_Tool

object_labels = ["baseball", "basket"]
languages = ["en", "de"]
detail = 0

try:
    result = Text_Detector_Tool.execute(image='path_to_image.png', languages=languages, detail=detail)
except Exception:
    result = []

final_result = []
for block in result:
    if "baseball" in block[1]:
        block_num = "baseball"
        if block_num in block[0]:
            block_num += "_detected"
        if block_num != "basket":
            final_result.append(block)
    if "basket" in block[1]:
        block_num = "basket"
        if block_num in block[0]:
            block_num += "_detected"
        if block_num != "baseball":
            final_result.append(block)    

if not final_result:
    final_result = "detected_objects"
generated_lines = []
for i in final_result:
    i = i[1]
    lang = i.split('_', 1)[0].lower()
    if i.split('$', 1)[1]:
        lang += '_detected'  
    i = i.replace('_', '$', 1)[0]
    lang = lang.lstrip('$')

    if i == block_num:
        lang += '_detected'
    if i != block_num:
        lang = lang.replace(block_num, "")
    lang += '.txt'
    if ' ' not in lang:
        lang = lang[0] + '$' + lang

    lang = lang.lstrip('$')
    lang = lang[0:4] + ' ' + block_num
    lang = lang.replace(' ', ' _ ')
    lang = lang.replace(', ', '_')
    generated_lines.append(lang)

    if block_num not in langs:
        langs.append(block_num)

file_path = 'detected_objects.txt'
